import sympy as s
x,y,z=s.symbols('x y z',real=True)
rows=[(4,(y*y-2*x,2*x*y),x*y*y-x*x),(5,(y*y*s.exp(x*y),(1+x*y)*s.exp(x*y)),y*s.exp(x*y)),(6,(y*s.exp(x),s.exp(x)+s.exp(y)),y*s.exp(x)+s.exp(y)),(7,(y*s.exp(x)+s.sin(y),s.exp(x)+x*s.cos(y)),y*s.exp(x)+x*s.sin(y)),(8,(2*x*y+y**-2,x*x-2*x*y**-3),x*x*y+x*y**-2),(9,(y*y*s.cos(x)+s.cos(y),2*y*s.sin(x)-x*s.sin(y)),y*y*s.sin(x)+x*s.cos(y)),(10,(s.log(y)+y/x,s.log(x)+x/y),x*s.log(y)+y*s.log(x)),(11,(2*x*y,x*x),x*x*y),(12,(2*x*y,x*x+s.sin(y)),x*x*y-s.cos(y)),(13,(3*x*x+y*y,2*x*y),x**3+x*y*y),(14,(s.sin(y)+s.exp(x),x*s.cos(y)),x*s.sin(y)+s.exp(x)),(15,(y*s.exp(x*y),x*s.exp(x*y)),s.exp(x*y)),(17,(2*x,4*y),x*x+2*y*y),(18,(3+2*x*y*y,2*x*x*y),3*x+x*x*y*y),(19,(x*x*y**3,x**3*y*y),x**3*y**3/3),(20,((1+x*y)*s.exp(x*y),x*x*s.exp(x*y)),x*s.exp(x*y)),(21,(2*x*y,x*x+2*y*z,y*y),x*x*y+y*y*z),(22,(y*y*z+2*x*z*z,2*x*y*z,x*y*y+2*x*x*z),x*y*y*z+x*x*z*z),(23,(y*z*s.exp(x*z),s.exp(x*z),x*y*s.exp(x*z)),y*s.exp(x*z)),(24,(s.sin(y),x*s.cos(y)+s.cos(z),-y*s.sin(z)),x*s.sin(y)+y*s.cos(z)),(25,(2*x*s.exp(-y),2*y-x*x*s.exp(-y)),x*x*s.exp(-y)+y*y),(26,(s.sin(y),x*s.cos(y)-s.sin(y)),x*s.sin(y)+s.cos(y)),(29,(x**3,y**3),(x**4+y**4)/4),(30,(2*x+y,x),x*x+x*y),(33,(s.sin(y),1+x*s.cos(y)),x*s.sin(y)+y)]
for n,F,f in rows:
 assert all(s.simplify(s.diff(f,v)-F[i])==0 for i,v in enumerate([x,y,z][:len(F)])),n
for n,A,B,w in [(17,(4,-2),(1,1),-21),(18,(1,1),(4,s.Rational(1,4)),9),(19,(0,0),(-1,3),-9),(20,(1,0),(0,2),-1),(21,(2,-3,1),(-5,1,2),30),(22,(0,1,0),(1,2,1),5),(23,(1,-1,0),(5,3,0),4),(24,(0,0,0),(1,s.pi/2,s.pi),1-s.pi/2),(25,(1,0),(2,1),4/s.E),(26,(2,0),(1,s.pi),-2),(29,(1,0),(2,2),s.Rational(31,4)),(30,(1,1),(4,3),26)]:
 f=next(f for m,F,f in rows if n==m);value=f.subs(dict(zip([x,y,z],B)))-f.subs(dict(zip([x,y,z],A)));assert s.simplify(value-w)==0,(n,value,w)
print('25 potentials and 12 endpoint differences verified.')
